style.css:
@-moz-document domain("gamblit.net") {
/* === PAGE BACKGROUND === */
    body {
        background-image: url("https://motionbgs.com/i/c/364x205/media/3676/luffy-dark.jpg") !important;
        background-repeat: no-repeat !important;
        background-position: center center !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-color: #000000 !important;
    }

    /* === HIDE ORIGINAL LOGO IMAGE === */
    img[src*="assets/logo-pS6_emEH.png"] {
        visibility: hidden !important;
        width: 0 !important;
        height: 0 !important;
    }

    /* === INSERT DARK LUFFY LOGO IN SAME PLACE === */
    img[src*="assets/logo-pS6_emEH.png"]::before {
        content: "";
        display: block !important;
        width: 120px !important;
        height: 120px !important;
        background-image: url("https://motionbgs.com/i/c/364x205/media/3676/luffy-dark.jpg") !important; /* Dark Luffy image URL */
        background-repeat: no-repeat !important;
        background-position: center !important;
        background-size: contain !important;
    }
}
